CREATE DATABASE IF NOT EXISTS visitor_slideshow; USE visitor_slideshow;
CREATE TABLE IF NOT EXISTS visitors(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,phone VARCHAR(20) NOT NULL UNIQUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS photos(id INT AUTO_INCREMENT PRIMARY KEY,visitor_id INT NOT NULL,file_name VARCHAR(255) NOT NULL,file_path VARCHAR(500) NOT NULL,consent_given TINYINT(1) NOT NULL DEFAULT 0,uploaded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(visitor_id) REFERENCES visitors(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS slideshow_queue(id INT AUTO_INCREMENT PRIMARY KEY,photo_id INT NOT NULL,status ENUM('pending','displayed') NOT NULL DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,displayed_at DATETIME NULL,FOREIGN KEY(photo_id) REFERENCES photos(id) ON DELETE CASCADE);
